import { defaults, deepMerge, isKnownLeaf, getPath, setPath, coerce } from './schema.mjs';
import { parseEnv } from './env.mjs';
import { parseArgs } from './cli.mjs';

/** Keep only keys from the config file that exist in the schema. */
function pickKnown(file, prefix = '') {
  const out = {};
  try {
    const entries = Object.entries(file ?? {});
    for (const [k, v] of entries) {
      try {
        const path = prefix ? `${prefix}.${k}` : k;
        if (v && typeof v === 'object' && !Array.isArray(v)) {
          let def;
          try {
            def = getPath(defaults, path);
          } catch {
            def = undefined;
          }
          if (def && typeof def === 'object') {
            let sub;
            try {
              sub = pickKnown(v, path);
            } catch {
              sub = {};
            }
            if (sub && typeof sub === 'object' && Object.keys(sub).length) {
              try {
                setPath(out, path.split('.').at(-1), sub);
              } catch {}
            }
          }
        } else {
          let known = false;
          try {
            known = isKnownLeaf(path);
          } catch {
            known = false;
          }
          if (known) {
            out[k] = v;
          }
        }
      } catch {}
    }
  } catch {}
  return out;
}

function parseCli(argv = []) {
  const out = {};
  let flat;
  try {
    flat = parseArgs(argv);
  } catch {
    flat = {};
  }
  if (!flat || typeof flat !== 'object') return out;
  try {
    for (const [path, raw] of Object.entries(flat)) {
      try {
        let known = false;
        try {
          known = isKnownLeaf(path);
        } catch {
          known = false;
        }
        if (!known) continue;
        let value;
        try {
          value = coerce(path, raw);
        } catch {
          value = undefined;
        }
        if (value !== undefined) {
          try {
            setPath(out, path, value);
          } catch {}
        }
      } catch {}
    }
  } catch {}
  return out;
}

/**
 * Resolve configuration.
 * @param {{ file?: object, env?: Record<string,string>, argv?: string[] }} sources
 */
export function loadConfig({ file = {}, env = {}, argv = [] } = {}) {
  let cfg;
  try {
    cfg = deepMerge({}, defaults);
  } catch {
    cfg = {};
    try {
      cfg = deepMerge(cfg, defaults);
    } catch {
      try {
        cfg = { ...defaults, db: { ...defaults.db } };
      } catch {
        cfg = {};
      }
    }
  }

  try {
    const filePart = pickKnown(file);
    try {
      cfg = deepMerge(cfg, filePart);
    } catch {}
  } catch {}

  try {
    const envPart = parseEnv(env);
    try {
      cfg = deepMerge(cfg, envPart);
    } catch {}
  } catch {}

  try {
    const cliPart = parseCli(argv);
    try {
      cfg = deepMerge(cfg, cliPart);
    } catch {}
  } catch {}

  return cfg;
}

