// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }
    let onAbort;
    const t = setTimeout(() => {
      if (signal && onAbort) {
        try {
          signal.removeEventListener('abort', onAbort);
        } catch {}
      }
      resolve();
    }, ms);
    if (signal) {
      onAbort = () => {
        clearTimeout(t);
        reject(signal.reason);
      };
      signal.addEventListener('abort', onAbort, { once: true });
    }
  });
}

export async function retry(fn, opts = {}) {
  const { retries = 3, baseDelayMs = 100, factor = 2, sleep = defaultSleep, signal } = opts;

  if (signal?.aborted) {
    throw signal.reason;
  }

  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (signal?.aborted) {
      throw signal.reason;
    }

    try {
      let maybe;
      try {
        maybe = fn(attempt);
      } catch (syncErr) {
        throw syncErr;
      }
      return await Promise.resolve(maybe);
    } catch (err) {
      lastErr = err;

      if (signal?.aborted) {
        throw signal.reason;
      }

      if (err && err.retryable === false) {
        throw err;
      }

      if (attempt === retries) {
        throw err;
      }

      const delay = baseDelayMs * Math.pow(factor, attempt);

      try {
        // Defensive sleep with local abort race (do not trust sleep to respect signal)
        let abortHandler;
        let abortPromise;
        if (signal) {
          abortPromise = new Promise((_, reject) => {
            abortHandler = () => reject(signal.reason);
            signal.addEventListener('abort', abortHandler, { once: true });
          });
        }

        let sleepPromise;
        try {
          const maybeSleep = sleep(delay, signal);
          sleepPromise = Promise.resolve(maybeSleep);
        } catch (syncSleepErr) {
          sleepPromise = Promise.reject(syncSleepErr);
        }

        // Prevent unhandled rejection if abort wins
        sleepPromise.catch(() => {});

        try {
          if (signal) {
            await Promise.race([sleepPromise, abortPromise]);
          } else {
            await sleepPromise;
          }
        } finally {
          if (signal && abortHandler) {
            try {
              signal.removeEventListener('abort', abortHandler);
            } catch {}
          }
        }
      } catch (sleepErr) {
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw sleepErr;
      }
    }
  }

  throw lastErr;
}

