// Rounding helpers for integer-cent money math.

/**
 * Round a cent amount half-up (2.5 -> 3, -2.5 -> -2), i.e. Math.round semantics.
 * Used by: invoice.mjs (line tax), statement.mjs (late fees - half-up is
 * written into the customer agreement, do not change for statements).
 */
export function roundCents(x) {
  return Math.round(x);
}

/**
 * Banker's rounding (round half to even), symmetric for negatives:
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4.
 * Non-half values round to nearest.
 */
export function roundHalfEven(x) {
  if (!Number.isFinite(x)) {
    return Math.round(x);
  }
  if (x < 0) {
    return -roundHalfEven(-x);
  }
  const floor = Math.floor(x);
  const frac = x - floor;
  const EPS = 1e-12;
  if (Math.abs(frac - 0.5) < EPS) {
    return floor % 2 === 0 ? floor : floor + 1;
  }
  return frac < 0.5 ? floor : floor + 1;
}

/**
 * Divide numer/denom and round half-even, symmetric for negatives.
 * Uses exact integer arithmetic when both args are integers to avoid
 * floating-point tie mis-detection.
 */
export function roundHalfEvenDiv(numer, denom) {
  if (!Number.isFinite(numer) || !Number.isFinite(denom)) {
    return roundHalfEven(numer / denom);
  }
  if (denom <= 0) throw new RangeError('denom must be positive');
  if (numer < 0) {
    return -roundHalfEvenDiv(-numer, denom);
  }
  if (Number.isInteger(numer) && Number.isInteger(denom)) {
    const q = Math.floor(numer / denom);
    const r = numer % denom;
    const half = denom / 2;
    if (r < half) return q;
    if (r > half) return q + 1;
    return q % 2 === 0 ? q : q + 1;
  }
  return roundHalfEven(numer / denom);
}

