// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    let settled = false;
    let timer = null;

    const cleanup = () => {
      if (signal) {
        signal.removeEventListener('abort', onAbort);
      }
    };

    const onAbort = () => {
      if (settled) return;
      settled = true;
      if (timer !== null) {
        clearTimeout(timer);
        timer = null;
      }
      cleanup();
      reject(signal.reason);
    };

    const onResolve = () => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve();
    };

    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }

    timer = setTimeout(onResolve, ms);

    if (signal) {
      signal.addEventListener('abort', onAbort, { once: true });
    }
  });
}

function sleepWithAbort(sleepFn, ms, signal) {
  return new Promise((resolve, reject) => {
    let settled = false;
    let abortHandler = null;

    const cleanup = () => {
      if (signal && abortHandler) {
        signal.removeEventListener('abort', abortHandler);
      }
    };

    abortHandler = () => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(signal.reason);
    };

    if (signal) {
      if (signal.aborted) {
        reject(signal.reason);
        return;
      }
      signal.addEventListener('abort', abortHandler, { once: true });
    }

    let sleepResult;
    try {
      sleepResult = sleepFn(ms, signal);
    } catch (syncErr) {
      if (!settled) {
        settled = true;
        cleanup();
        if (signal?.aborted) {
          reject(signal.reason);
        } else {
          reject(syncErr);
        }
      }
      return;
    }

    Promise.resolve(sleepResult).then(
      (value) => {
        if (settled) return;
        settled = true;
        cleanup();
        resolve(value);
      },
      (err) => {
        if (settled) return;
        settled = true;
        cleanup();
        if (signal?.aborted) {
          reject(signal.reason);
        } else {
          reject(err);
        }
      }
    );
  });
}

export async function retry(fn, opts = {}) {
  const { retries = 3, baseDelayMs = 100, factor = 2, sleep = defaultSleep, signal } = opts;

  const checkAborted = () => {
    if (signal?.aborted) {
      throw signal.reason;
    }
  };

  let lastErr;

  for (let attempt = 0; attempt <= retries; attempt++) {
    checkAborted();

    try {
      let result;
      try {
        result = fn(attempt);
      } catch (syncErr) {
        throw syncErr;
      }
      return await result;
    } catch (err) {
      if (signal?.aborted) {
        throw signal.reason;
      }

      if (err && err.retryable === false) {
        throw err;
      }

      lastErr = err;

      if (attempt === retries) {
        break;
      }

      checkAborted();

      const delay = baseDelayMs * Math.pow(factor, attempt);

      try {
        await sleepWithAbort(sleep, delay, signal);
      } catch (sleepErr) {
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw sleepErr;
      }
    }
  }

  throw lastErr;
}

