// Rounding helpers for integer-cent money math.

/**
 * Round a cent amount half-up (2.5 -> 3, -2.5 -> -2), i.e. Math.round semantics.
 * Used by: invoice.mjs (line tax), statement.mjs (late fees - half-up is
 * written into the customer agreement, do not change for statements).
 */
export function roundCents(x) {
  return Math.round(x);
}

/**
 * Banker's rounding (round half to even).
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4
 * Used by invoice tax.
 */
export function roundCentsHalfEven(x) {
  if (!Number.isFinite(x)) {
    return Math.round(x);
  }
  const sign = x < 0 ? -1 : 1;
  const abs = Math.abs(x);
  const floor = Math.floor(abs);
  const frac = abs - floor;
  const EPS = 1e-12;
  let result;
  if (frac < 0.5 - EPS) {
    result = floor;
  } else if (frac > 0.5 + EPS) {
    result = floor + 1;
  } else {
    // exactly half -> to even
    result = (floor % 2 === 0) ? floor : floor + 1;
  }
  result = sign * result;
  // normalize -0 to 0
  return result === 0 ? 0 : result;
}

// Aliases for convenience
// eslint-disable-next-line no-unused-vars
export const roundCentsEven = roundCentsHalfEven;
export const roundCentsBankers = roundCentsHalfEven;

