import { defaults, deepMerge, isKnownLeaf, getPath, setPath, coerce } from './schema.mjs';
import { parseEnv } from './env.mjs';
import { parseArgs } from './cli.mjs';

/** Keep only keys from the config file that exist in the schema. */
function pickKnown(file, prefix = '') {
  const out = {};
  let entries;
  try {
    entries = Object.entries(file ?? {});
  } catch {
    return out;
  }
  for (const [k, v] of entries) {
    let path;
    try {
      path = prefix ? `${prefix}.${k}` : k;
    } catch {
      continue;
    }
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      let def;
      try {
        def = getPath(defaults, path);
      } catch {
        continue;
      }
      if (def && typeof def === 'object') {
        let sub;
        try {
          sub = pickKnown(v, path);
        } catch {
          continue;
        }
        try {
          if (sub && typeof sub === 'object' && Object.keys(sub).length) {
            let leaf;
            try {
              leaf = path.split('.').at(-1);
            } catch {
              leaf = k;
            }
            setPath(out, leaf, sub);
          }
        } catch {
          continue;
        }
      }
    } else {
      let known = false;
      try {
        known = isKnownLeaf(path);
      } catch {
        continue;
      }
      if (known) {
        try {
          out[k] = v;
        } catch {
          continue;
        }
      }
    }
  }
  return out;
}

function parseCli(argv) {
  const out = {};
  let flat;
  try {
    flat = parseArgs(argv);
  } catch {
    return out;
  }
  if (!flat || typeof flat !== 'object' || Array.isArray(flat)) return out;
  let entries;
  try {
    entries = Object.entries(flat);
  } catch {
    return out;
  }
  for (const [path, raw] of entries) {
    let known = false;
    try {
      known = isKnownLeaf(path);
    } catch {
      continue;
    }
    if (!known) continue;
    let coerced;
    try {
      coerced = coerce(path, raw);
    } catch {
      continue;
    }
    if (coerced === undefined) continue;
    try {
      setPath(out, path, coerced);
    } catch {
      continue;
    }
  }
  return out;
}

/**
 * Resolve configuration.
 * @param {{ file?: object, env?: Record<string,string>, argv?: string[] }} sources
 */
export function loadConfig({ file = {}, env = {}, argv = [] } = {}) {
  let cfg;
  try {
    cfg = deepMerge({}, defaults);
  } catch {
    cfg = {};
    try {
      const copy = {};
      for (const [k, v] of Object.entries(defaults ?? {})) {
        if (v && typeof v === 'object' && !Array.isArray(v)) {
          try {
            copy[k] = { ...v };
          } catch {
            copy[k] = v;
          }
        } else {
          copy[k] = v;
        }
      }
      cfg = copy;
    } catch {
      cfg = {};
    }
  }

  let filePart = {};
  try {
    filePart = pickKnown(file);
  } catch {
    filePart = {};
  }
  try {
    const merged = deepMerge(cfg, filePart);
    if (merged && typeof merged === 'object') cfg = merged;
  } catch {
    // keep previous cfg
  }

  let envPart = {};
  try {
    envPart = parseEnv(env);
  } catch {
    envPart = {};
  }
  try {
    const merged = deepMerge(cfg, envPart);
    if (merged && typeof merged === 'object') cfg = merged;
  } catch {}

  let cliPart = {};
  try {
    cliPart = parseCli(argv);
  } catch {
    cliPart = {};
  }
  try {
    const merged = deepMerge(cfg, cliPart);
    if (merged && typeof merged === 'object') cfg = merged;
  } catch {}

  return cfg;
}

