// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }
    let abortHandler;
    const t = setTimeout(() => {
      if (signal && abortHandler) {
        signal.removeEventListener('abort', abortHandler);
      }
      resolve();
    }, ms);
    if (signal) {
      abortHandler = () => {
        clearTimeout(t);
        reject(signal.reason);
      };
      signal.addEventListener('abort', abortHandler, { once: true });
    }
  });
}

export async function retry(fn, opts = {}) {
  const { retries = 3, baseDelayMs = 100, factor = 2, sleep = defaultSleep, signal } = opts;

  if (signal?.aborted) {
    throw signal.reason;
  }

  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (signal?.aborted) {
      throw signal.reason;
    }

    try {
      // Defensive invocation of fn with local cancellation race
      let abortHandler;
      let abortPromise;
      if (signal) {
        abortPromise = new Promise((_, reject) => {
          abortHandler = () => reject(signal.reason);
          signal.addEventListener('abort', abortHandler, { once: true });
        });
      }

      let maybePromise;
      try {
        maybePromise = fn(attempt);
      } catch (syncErr) {
        if (signal && abortHandler) {
          signal.removeEventListener('abort', abortHandler);
        }
        throw syncErr;
      }

      try {
        if (signal) {
          const result = await Promise.race([Promise.resolve(maybePromise), abortPromise]);
          return result;
        } else {
          const result = await Promise.resolve(maybePromise);
          return result;
        }
      } finally {
        if (signal && abortHandler) {
          signal.removeEventListener('abort', abortHandler);
        }
      }
    } catch (err) {
      lastErr = err;

      if (signal?.aborted) {
        throw signal.reason;
      }

      if (err && err.retryable === false) {
        throw err;
      }

      if (attempt === retries) {
        throw err;
      }

      const delay = baseDelayMs * Math.pow(factor, attempt);

      if (signal?.aborted) {
        throw signal.reason;
      }

      // Defensive sleep with local cancellation race
      let sleepAbortHandler;
      let sleepAbortPromise;
      if (signal) {
        sleepAbortPromise = new Promise((_, reject) => {
          sleepAbortHandler = () => reject(signal.reason);
          signal.addEventListener('abort', sleepAbortHandler, { once: true });
        });
      }

      let sleepPromise;
      try {
        sleepPromise = sleep(delay, signal);
      } catch (syncSleepErr) {
        if (signal && sleepAbortHandler) {
          signal.removeEventListener('abort', sleepAbortHandler);
        }
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw syncSleepErr;
      }

      try {
        if (signal) {
          await Promise.race([Promise.resolve(sleepPromise), sleepAbortPromise]);
        } else {
          await Promise.resolve(sleepPromise);
        }
      } catch (sleepErr) {
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw sleepErr;
      } finally {
        if (signal && sleepAbortHandler) {
          signal.removeEventListener('abort', sleepAbortHandler);
        }
      }
    }
  }

  throw lastErr;
}

