import { roundCentsEven, roundDivHalfEven } from './rounding.mjs';

/**
 * @param {Array<{ sku: string, qty: number, unitCents: number }>} lines
 * @param {{ taxBps: number }} opts  tax rate in basis points (2000 = 20%)
 */
export function buildInvoice(lines, { taxBps }) {
  if (!Number.isInteger(taxBps) || taxBps < 0) throw new RangeError('taxBps must be a non-negative integer');

  let out;
  try {
    out = lines.map((l) => {
      let netCents;
      try {
        netCents = l.qty * l.unitCents;
      } catch (e) {
        throw e;
      }

      let taxCents;
      try {
        const raw = netCents * taxBps;
        let res;
        if (Number.isInteger(raw)) {
          res = roundDivHalfEven(raw, 10000);
        } else {
          // fallback for non-integer net (e.g. fractional qty) - use float bankers rounding
          res = roundCentsEven(raw / 10000);
        }
        // Defensive: never trust helper to respect sync contract
        if (res && typeof res.then === 'function') {
          throw new TypeError('rounding returned Promise in sync context');
        }
        taxCents = res;
      } catch (e) {
        // Failure isolation: do not persist partial line
        throw e;
      }

      // Return new object, do not mutate caller's input
      return { sku: l.sku, qty: l.qty, unitCents: l.unitCents, netCents, taxCents };
    });
  } catch (e) {
    // Ensure no stale partial result escapes
    throw e;
  }

  let subtotalCents;
  let taxCentsTotal;
  try {
    subtotalCents = out.reduce((s, l) => s + l.netCents, 0);
    taxCentsTotal = out.reduce((s, l) => s + l.taxCents, 0);
  } catch (e) {
    throw e;
  }

  return {
    lines: out,
    subtotalCents,
    taxCents: taxCentsTotal,
    totalCents: subtotalCents + taxCentsTotal,
    taxBps,
  };
}

