// Rounding helpers for integer-cent money math.

/**
 * Round a cent amount half-up (2.5 -> 3, -2.5 -> -2), i.e. Math.round semantics.
 * Used by: statement.mjs (late fees - half-up is written into the customer agreement, do not change for statements).
 */
export function roundCents(x) {
  return Math.round(x);
}

/**
 * Banker's rounding (round half to even).
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4
 * Ties (exactly .5) go to nearest even integer.
 */
export function roundCentsEven(x) {
  try {
    if (!Number.isFinite(x)) {
      return Math.round(x);
    }
    const floor = Math.floor(x);
    const ceil = Math.ceil(x);
    if (floor === ceil) {
      return floor;
    }
    const diff = x - floor;
    const EPS = 1e-12;
    if (Math.abs(diff - 0.5) < EPS) {
      // tie -> even
      return floor % 2 === 0 ? floor : ceil;
    }
    return diff < 0.5 ? floor : ceil;
  } catch (e) {
    // Failure isolation: do not cache failure, propagate
    throw e;
  }
}

/**
 * Integer division with banker's rounding.
 * Rounds dividend/divisor to nearest integer, ties to even.
 * divisor must be positive (normalized if negative).
 */
export function roundDivHalfEven(dividend, divisor) {
  try {
    if (!Number.isFinite(dividend) || !Number.isFinite(divisor)) {
      return Math.round(dividend / divisor);
    }
    if (divisor === 0) {
      return dividend >= 0 ? Infinity : -Infinity;
    }
    if (divisor < 0) {
      dividend = -dividend;
      divisor = -divisor;
    }
    const sign = dividend < 0 ? -1 : 1;
    const absDividend = Math.abs(dividend);
    const q = Math.trunc(absDividend / divisor);
    const r = absDividend % divisor;
    const twiceR = r * 2;
    let roundedAbs;
    if (twiceR < divisor) {
      roundedAbs = q;
    } else if (twiceR > divisor) {
      roundedAbs = q + 1;
    } else {
      // exactly half
      roundedAbs = q % 2 === 0 ? q : q + 1;
    }
    if (roundedAbs === 0) return 0;
    return sign * roundedAbs;
  } catch (e) {
    throw e;
  }
}

