      if (!known) continue;
      let value;
      try {
        value = coerce(path, raw);
      } catch {
        value = undefined;
      }
      if (value !== undefined) {
        try {
          setPath(out, path, value);
        } catch {}
      }
    } catch {
      continue;
    }
  }
  return out;
}

