import { ApiError } from './errors.mjs';
import { encodeCursor, decodeCursor } from './cursor.mjs';

export const DEFAULT_PAGE_SIZE = 20;
export const MAX_PAGE_SIZE = 100;

export function parsePageSize(raw) {
  if (raw === undefined) return DEFAULT_PAGE_SIZE;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 1 || n > MAX_PAGE_SIZE) {
    throw new ApiError(400, `pageSize must be an integer between 1 and ${MAX_PAGE_SIZE}`);
  }
  return n;
}

/**
 * GET /items
 * @param {import('./db.mjs').ItemsDb} db
 * @param {Record<string, string>} query  raw query-string values
 */
export function listItems(db, query = {}) {
  const hasPage = Object.prototype.hasOwnProperty.call(query, 'page');
  const hasCursor = Object.prototype.hasOwnProperty.call(query, 'cursor');

  if (hasPage && hasCursor) {
    throw new ApiError(400, 'page and cursor are mutually exclusive');
  }

  let pageSize;
  try {
    pageSize = parsePageSize(query.pageSize);
  } catch (e) {
    if (e instanceof ApiError) throw e;
    throw e;
  }

  if (hasCursor) {
    const rawCursor = query.cursor;

    let cursorObj = null;
    if (rawCursor !== '') {
      if (typeof rawCursor !== 'string') {
        throw new ApiError(400, 'invalid cursor');
      }
      try {
        const decoded = decodeCursor(rawCursor);
        if (
          typeof decoded.createdAt !== 'number' ||
          !Number.isFinite(decoded.createdAt) ||
          typeof decoded.id !== 'number' ||
          !Number.isFinite(decoded.id)
        ) {
          throw new Error('bad cursor');
        }
        cursorObj = decoded;
      } catch {
        throw new ApiError(400, 'invalid cursor');
      }
    }

    let all;
    try {
      all = db.listAll();
      if (all && typeof all.then === 'function') {
        try {
          all.then(() => {}, () => {});
        } catch {}
        throw new Error('db.listAll returned promise');
      }
    } catch (e) {
      if (e instanceof ApiError) throw e;
      throw e;
    }

    let filtered;
    try {
      if (cursorObj === null) {
        filtered = all;
      } else {
        filtered = all.filter((item) => {
          return item.createdAt < cursorObj.createdAt || (item.createdAt === cursorObj.createdAt && item.id < cursorObj.id);
        });
      }
    } catch (e) {
      throw e;
    }

    let pageItems;
    try {
      pageItems = filtered.slice(0, pageSize);
    } catch (e) {
      throw e;
    }

    let nextCursor = null;
    if (filtered.length > pageSize) {
      const last = pageItems[pageItems.length - 1];
      try {
        const enc = encodeCursor({ createdAt: last.createdAt, id: last.id });
        if (enc && typeof enc.then === 'function') {
          try {
            enc.then(() => {}, () => {});
          } catch {}
          throw new Error('encodeCursor returned promise');
        }
        nextCursor = enc;
      } catch (e) {
        if (e instanceof ApiError) throw e;
        throw e;
      }
    }

    return { items: pageItems, nextCursor };
  } else {
    let page;
    try {
      page = query.page === undefined ? 1 : Number(query.page);
    } catch (e) {
      throw e;
    }
    if (!Number.isInteger(page) || page < 1) throw new ApiError(400, 'page must be a positive integer');

    let all;
    try {
      all = db.listAll();
      if (all && typeof all.then === 'function') {
        try {
          all.then(() => {}, () => {});
        } catch {}
        throw new Error('db.listAll returned promise');
      }
    } catch (e) {
      if (e instanceof ApiError) throw e;
      throw e;
    }

    let sliced;
    let start;
    try {
      start = (page - 1) * pageSize;
      sliced = all.slice(start, start + pageSize);
    } catch (e) {
      throw e;
    }

    return { items: sliced, page, pageSize, total: all.length };
  }
}

