// Least-recently-used map. Iteration order of `this.map` is oldest -> newest.
export class LRU {
  constructor({ max = 100, onEvict } = {}) {
    if (!(max >= 1)) throw new RangeError('max must be >= 1');
    this.max = max;
    this.map = new Map();
    this.hits = 0;
    this.misses = 0;
    this.onEvict = typeof onEvict === 'function' ? onEvict : undefined;
  }

  get size() {
    return this.map.size;
  }

  has(key) {
    return this.map.has(key);
  }

  /** Read without touching recency or stats. */
  peek(key) {
    return this.map.get(key);
  }

  get(key) {
    if (!this.map.has(key)) {
      this.misses++;
      return undefined;
    }
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);
    this.hits++;
    return value;
  }

  _emitEvict(key, value, reason) {
    if (!this.onEvict) return;
    try {
      const result = this.onEvict(key, value, reason);
      if (result && typeof result.then === 'function') {
        result.then(null, () => {});
      }
    } catch (_) {
      // Defensive: keep LRU operational if hook throws
    }
  }

  set(key, value) {
    if (this.map.has(key)) {
      // Overwrite is an update, not an eviction - do not fire hook
      this.map.delete(key);
    }
    this.map.set(key, value);
    while (this.map.size > this.max) {
      const oldestKey = this.map.keys().next().value;
      const oldestValue = this.map.get(oldestKey);
      // Remove first so has() is false inside hook
      this.map.delete(oldestKey);
      this._emitEvict(oldestKey, oldestValue, 'capacity');
    }
    return this;
  }

  delete(key) {
    if (!this.map.has(key)) {
      return false;
    }
    const value = this.map.get(key);
    this.map.delete(key);
    this._emitEvict(key, value, 'delete');
    return true;
  }

  clear() {
    const entries = [...this.map.entries()];
    try {
      for (const [key, value] of entries) {
        if (this.map.has(key)) {
          this.map.delete(key);
        }
        this._emitEvict(key, value, 'clear');
      }
    } finally {
      // Guaranteed cleanup even if hook throws
      this.map.clear();
    }
  }

  /** Keys from least to most recently used. */
  keys() {
    return [...this.map.keys()];
  }

  stats() {
    return { size: this.map.size, max: this.max, hits: this.hits, misses: this.misses };
  }
