export class SessionStore {
  constructor({ maxInMemory = 1000, backing = new BackingStore() } = {}) {
    this.backing = backing;
    this.lru = new LRU({
      max: maxInMemory,
      onEvict: (key, value, reason) => {
        if (reason !== 'capacity') return;
        try {
          const result = this.backing.save(key, value);
          if (result && typeof result.then === 'function') {
            result.then(null, () => {});
          }
        } catch (_) {
          // Defensive: failure isolation - don't persist failure as success
        }
      },
    });
  }

  create(id, data = {}) {
    const session = { id, data };
    try {
      const result = this.lru.set(id, session);
      if (result && typeof result.then === 'function') {
        result.then(null, () => {});
      }
    } catch (_) {}
    return session;
  }

  get(id) {
    let session;
    try {
      const result = this.lru.get(id);
      if (result && typeof result.then === 'function') {
        result.then(null, () => {});
        session = undefined;
      } else {
        session = result;
      }
    } catch (_) {
      session = undefined;
    }

    if (session !== undefined) {
      return session;
    }

    let loaded;
    try {
      const result = this.backing.load(id);
      if (result && typeof result.then === 'function') {
        result.then(null, () => {});
        loaded = undefined;
      } else {
        loaded = result;
      }
    } catch (_) {
      loaded = undefined;
