// Least-recently-used map. Iteration order of `this.map` is oldest -> newest.
export class LRU {
  constructor({ max = 100, onEvict } = {}) {
    if (!(max >= 1)) throw new RangeError('max must be >= 1');
    if (onEvict !== undefined && typeof onEvict !== 'function') {
      throw new TypeError('onEvict must be a function');
    }
    this.max = max;
    this.map = new Map();
    this.hits = 0;
    this.misses = 0;
    this._onEvict = onEvict;
  }

  get size() {
    return this.map.size;
  }

  has(key) {
    return this.map.has(key);
  }

  /** Read without touching recency or stats. */
  peek(key) {
    return this.map.get(key);
  }

  get(key) {
    if (!this.map.has(key)) {
      this.misses++;
      return undefined;
    }
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);
    this.hits++;
    return value;
  }

  set(key, value) {
    if (this.map.has(key)) {
      // update, not an eviction
      this.map.delete(key);
    }
    this.map.set(key, value);
    while (this.map.size > this.max) {
      const oldestKey = this.map.keys().next().value;
      const oldestValue = this.map.get(oldestKey);
      this.map.delete(oldestKey);
      this._emitEvict(oldestKey, oldestValue, 'capacity');
    }
    return this;
  }

  delete(key) {
    if (!this.map.has(key)) {
      return false;
    }
    const value = this.map.get(key);
    this.map.delete(key);
    this._emitEvict(key, value, 'delete');
    return true;
  }

  clear() {
    const entries = [...this.map.entries()];
    for (const [k, v] of entries) {
      if (this.map.has(k)) {
        this.map.delete(k);
      }
      this._emitEvict(k, v, 'clear');
    }
  }

  /** Keys from least to most recently used. */
  keys() {
    return [...this.map.keys()];
  }

  stats() {
    return { size: this.map.size, max: this.max, hits: this.hits, misses: this.misses };
  }

  _emitEvict(key, value, reason) {
    const fn = this._onEvict;
    if (typeof fn !== 'function') return;
    try {
      const result = fn(key, value, reason);
      if (result && typeof result.then === 'function') {
        result.then(null, () => {});
      }
    } catch (_) {
      // defensive: swallow hook errors so LRU operation still succeeds
    }
  }
}

